import json,base64,sys,re,glob
def b(s):
    s=s+'='*(-len(s)%4)
    return base64.urlsafe_b64decode(s).decode('utf-8','replace')
def walk(p,out):
    mt=p.get('mimeType','')
    d=p.get('body',{}).get('data')
    if d and mt.startswith('text/plain'): out.append(b(d))
    elif d and mt.startswith('text/html') and not any(x for x in out): out.append(re.sub('<[^>]+>',' ',b(d)))
    for c in p.get('parts',[]) or []: walk(c,out)
def show(t,maxc=3000):
    for m in t.get('messages',[t]):
        h={x['name']:x['value'] for x in m['payload'].get('headers',[])}
        print('-----',h.get('Date'),'|',h.get('From'),'->',h.get('To'),'cc',h.get('Cc'),'|',h.get('Subject'))
        out=[];walk(m['payload'],out)
        txt='\n'.join(out)
        # strip quoted
        lines=[l for l in txt.split('\n') if not l.startswith('>')]
        print('\n'.join(lines)[:maxc])
for f in sys.argv[1:]:
    r=json.load(open(f))
    t=json.loads(r['result']) if isinstance(r,dict) and 'result' in r else r
    show(t)
